<template><main class="auth-shell"><section class="surface-card auth-panel"><p class="eyebrow">ELM LITE · 骑手端</p><h1>{{ registering ? '骑手注册' : '骑手登录' }}</h1><form class="form-grid" @submit.prevent="submit"><label>账号<input v-model.trim="form.username" required maxlength="50"></label><label>密码<input v-model="form.password" type="password" required minlength="8" maxlength="72"></label><label v-if="registering">姓名<input v-model.trim="form.displayName" required maxlength="50"></label><p v-if="error" role="alert" class="error-text">{{ error }}</p><button class="primary" :disabled="busy">{{ busy ? '提交中…' : registering ? '注册' : '登录' }}</button></form><button class="secondary" @click="registering=!registering;error=''">{{ registering ? '已有账号，去登录' : '注册骑手账号' }}</button></section></main></template>
<script setup>
import { reactive,ref } from 'vue'; import { useRouter } from 'vue-router'; import { loginRider,registerRider } from '@/api/rider'; import { setToken } from '@/utils/auth'
const router=useRouter(),registering=ref(false),busy=ref(false),error=ref(''); const form=reactive({username:'',password:'',displayName:''})
async function submit(){busy.value=true;error.value='';try{if(registering.value){await registerRider(form);registering.value=false}else{const r=await loginRider(form);setToken(r.accessToken,'RIDER');await router.push('/rider')}}catch(e){error.value=e.response?.data?.msg||'提交错误，请重试'}finally{busy.value=false}}
</script>
